from app.classification_pipeline import (
    ClassificationPipeline
)

# SCC-110 entry point.
# Consumes inventory.json generated by SCC-39 extraction pipeline.
# benchmarking_automation\tests\us01_s4_run_pipeline.py

def main():

    pipeline = ClassificationPipeline()

    pipeline.run(
        inventory_path="tests/output/inventory.json",
        json_output_path=(
            "output/classified_inventory.json"
        ),
        excel_output_path=(
            "output/classified_inventory.xlsx"
        )
    )


if __name__ == "__main__":
    main()
